  holidays: HolidayBriefOut[];
  staff: RosterableStaffOut[];
}

export interface ShiftPatternOut {
  shift_pattern_id: number;
  name: string;
  start_time: string;
  /** Earlier than start_time for a night shift */
  end_time: string;
  grace_minutes: number;
