  department_name: string | null;
  /** A fixed default shift (null: works to the roster only) */
  default_shift_pattern_id: number | null;
  /** That default shift's weekly days off (ISO weekdays, 1 = Monday … 7 = Sunday); [] for roster-only staff */
  default_weekly_off_days: number[];
  /** Approved leave in the range (they cannot be rostered then) */
  leave: StaffLeaveOut[];
}

export interface StaffLeaveOut {
  employee_id: number;
  from_date: string;
  to_date: string;
  leave_type: "Annual" | "Casual" | "Sick" | "Maternity" | "Unpaid" | "Other";
}

export interface EntriesIn {
  entries: EntryIn[];
}

export interface EntryIn {
  employee_id: number;
  /** The date the shift STARTS (a night shift belongs to its start date) */
  roster_date: string;
  /** GET /rosters/staff → shift_patterns (HR: GET /hr/shift-patterns) */
  shift_pattern_id: number;
  duty_area?: "Ward" | "Department" | "Emergency" | "OT" | "Facility" | "Other";
  /** Required when duty_area is Ward */
  ward_id?: number | null;
  department_id?: number | null;
  zone_label?: string | null;
  /** Ward duties: the beds this nurse looks after */
  bed_ids?: number[];
  is_on_call?: boolean;
  notes?: string | null;
}

export interface EntryPatch {
  /** row_version you loaded (optimistic concurrency) */
  expected_version?: number | null;
  roster_date?: string | null;
  shift_pattern_id?: number | null;
  duty_area?: "Ward" | "Department" | "Emergency" | "OT" | "Facility" | "Other" | null;
  /** The ward (GET /beds/matrix?include_beds=false) */
  ward_id?: number | null;
  /** The department (GET /admin/departments) */
  department_id?: number | null;
  zone_label?: string | null;
  bed_ids?: number[] | null;
  is_on_call?: boolean | null;
  notes?: string | null;
}

export interface RosterReasonIn {
  reason: string;
}

export interface CopyIn {
  source_from: string;
  source_to: string;
  /** Where the copy starts, e.g. next Monday */
  target_from: string;
  /** The ward (GET /beds/matrix?include_beds=false) */
  ward_id?: number | null;
  /** The department (GET /admin/departments) */
  department_id?: number | null;
  staff_category?: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting" | null;
  /** Move everyone's pattern on by this many days within the period, wrapping round: 1 on a week makes each rest day move to the next weekday, so rest days (and Sunday duty) rotate week by week */
  rotate_days?: number;
}

