/** One person's roster week. */
export interface WeekStaffOut {
  employee_id: number;
  emp_number: string;
  full_name: string;
  designation: string;
  staff_category: "Clinical" | "Nursing" | "Administrative" | "Technical" | "SupportZeroInterface" | "Visiting";
  department_name: string | null;
  /** On a fixed schedule (a default shift) during the week */
  has_default_shift: boolean;
  duty_dates: string[];
  /** Days without a duty and without leave */
